import {allCardInstanceIds,createGame,gameStats,transition,viewFor,type GameCommand,type GameState} from '@madou/engine';
import {getAction} from '@madou/catalog';
import {assignCharacter,entropy,takeCard,trimHand,readySetup} from './scenario-tools.js';
export function makeReclaimCrystalScenario(players:{id:string;name:string}[],second=false):GameState{
 let s=createGame(players,entropy(),{startingSeat:0});const [a,b,c,d]=players.map(p=>p.id) as [string,string,string,string];assignCharacter(s,a,'占星術師のアルセイル');assignCharacter(s,b,'黒騎士ガーウィン');assignCharacter(s,c,'侍大将のシン');assignCharacter(s,d,'魔導王ガイナス');for(const p of Object.values(s.players))p.permanent={endurance:100,warrior_level:20,magic_level:20,spirit:20};const red=takeCard(s,a,'赤い水晶球') as 'a2-p03-r1c3',far=takeCard(s,a,'遠見の水晶球'),fate=takeCard(s,b,'命運凶変');trimHand(s,a,red,far);trimHand(s,b,fate);s.deck=[...s.deck.filter(id=>getAction(id)!.category!=='open'),...s.deck.filter(id=>getAction(id)!.category==='open')];
 function act(actorId:string,command:GameCommand){const input={actorId,command},e=entropy(),r=transition(s,input,e);if(!r.ok)throw Error(`CRYSTAL_RECLAIM_${command.type}_${r.code}`);if(JSON.stringify(r)!==JSON.stringify(transition(JSON.parse(JSON.stringify(s)),input,e)))throw Error('CRYSTAL_RECLAIM_REPLAY');s=r.state;const ids=allCardInstanceIds(s);if(ids.length!==220||new Set(ids).size!==220)throw Error('CRYSTAL_RECLAIM_CARDS');}
 function until(done:()=>boolean){for(let n=0;n<300;n++){if(done())return;const w=s.windows!.at(-1)!;act(w.participants[w.cursor]!,{type:'PASS'});}throw Error('CRYSTAL_RECLAIM_WINDOW');}
 readySetup(()=>s,id=>act(id,{type:'PASS_SETUP'}));act(a,{type:'START_TURN'});act(a,{type:'CHOOSE_DRAW',draw:false});if(!second)return s;act(a,{type:'PLAY_TURN_CARD',cardInstanceId:red});act(a,{type:'PASS'});act(b,{type:'PLAY_REACTION',cardInstanceId:fate,mode:'cancel',targetActionId:viewFor(s,b).reactionTargetActionId!});until(()=>s.windows?.at(-1)?.kind==='reclaim'&&viewFor(s,a).reclaim?.cardInstanceId===red);const choice=viewFor(s,a).reclaim!;act(a,{type:'CHOOSE_RECLAIM',decisionId:choice.decisionId,choice:'take',claimId:choice.claims[0]!.claimId});until(()=>!s.windows?.length);
 for(let n=0;n<60;n++){const id=s.seatOrder[s.turnSeat]!;if(s.phase==='action'){if(id===a)return s;act(id,{type:'PASS_ACTION'});}else if(s.phase==='withdrawal')act(id,{type:'PASS_WITHDRAWAL'});else if(s.phase==='hand-adjustment'){act(id,{type:'END_TURN',discardIds:s.players[id]!.hand.filter(x=>x!==red&&x!==far).slice(0,Math.max(0,s.players[id]!.hand.length-gameStats(s,id).handLimit))});until(()=>!s.windows?.length);}else if(s.phase==='turn-start')act(id,{type:'START_TURN'});else if(s.phase==='draw')act(id,{type:'CHOOSE_DRAW',draw:false});else throw Error('CRYSTAL_RECLAIM_TURN');}throw Error('CRYSTAL_RECLAIM_TURN_LIMIT');
}
